def link_existing_companies(apps, schema_editor):
    Contact = apps.get_model('crm', 'Contact')
    Company = apps.get_model('crm', 'Company')
    database = schema_editor.connection.alias
    companies_by_owner_and_name = {}

    contacts = Contact.objects.using(database).exclude(
        company_name_old='',
    ).exclude(company_name_old__isnull=True).order_by('pk')
